const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats=["Leaderboards", "SEO", "Marketing", "Productivity", "Agents", "Crypto", "Other", "Developer", "Health", "Business", "Games", "Ecommerce", "Travel", "Directories", "Agencies", "AI Media", "Social", "Education", "People", "Design", "Hiring", "Domains", "Security", "Sales", "News", "Real Estate", "Writing", "Audio", "Analytics"];
let session,account,people=[],filter='All people',search='',serverBase=Date.now(),clockBase=performance.now(),claimID=null,claimBusy=false,refreshBusy=false,toastTimer,claimError='',stateLoad=0;
const now=()=>serverBase+(performance.now()-clockBase);
const sync=d=>{if(d.serverNow){serverBase=d.serverNow;clockBase=performance.now()}return d};
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Please try again.');return sync(d)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
const date=t=>new Date(t).toLocaleString();
function remaining(t){const s=Math.max(0,Math.ceil((t-now())/1000));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':')}
function avatar(p){return '<div class="avatar">'+(p.photo?'<img src="'+esc(p.photo)+'" alt="'+esc(p.name)+'" loading="lazy" decoding="async" width="72" height="72"><span hidden>':'<span>')+esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))+'</span></div>'}
function profilePhotoField(p){return '<div class="profile-photo-editor"><div class="profile-photo-preview">'+avatar(p||{name:'Your photo'})+'<img id="selected-photo" hidden alt="Selected profile photo preview"></div><div class="profile-photo-controls"><label for="profile-photo-input">Profile picture <span>(optional)</span></label><input id="profile-photo-input" name="photo" type="file" accept="image/png,image/jpeg,image/webp" aria-describedby="profile-photo-help profile-photo-status"><p id="profile-photo-help">Choose a JPG, PNG or WebP up to 2 MB. This photo appears beside your name on the leaderboard.</p><p id="profile-photo-status" role="status" aria-live="polite">'+(p?.photo?'Your current photo is saved.':'Add a photo so people can recognize you.')+'</p></div></div>'}
function bindProfilePhoto(form){let previewURL=null;const input=form.elements.photo,preview=$('#selected-photo'),current=$('.profile-photo-preview .avatar'),status=$('#profile-photo-status');const clear=()=>{if(previewURL)URL.revokeObjectURL(previewURL);previewURL=null};input.onchange=()=>{clear();const file=input.files[0];preview.hidden=true;current.hidden=false;if(!file){status.textContent='No new photo selected.';return}if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2097152||file.size===0){input.value='';status.textContent='Choose a JPG, PNG or WebP image up to 2 MB.';return}previewURL=URL.createObjectURL(file);preview.src=previewURL;preview.hidden=false;current.hidden=true;status.textContent='Photo selected. Save your profile to upload it.'};return clear}
async function uploadProfilePhoto(photo){if(!photo||!photo.size)return;if(!['image/png','image/jpeg','image/webp'].includes(photo.type)||photo.size>2097152)throw Error('Choose a JPG, PNG or WebP image up to 2 MB.');const r=await fetch('/api/photo',{method:'POST',body:photo,headers:{'content-type':photo.type}}),d=await r.json();if(!r.ok)throw Error(d.error||'Photo upload failed. Please try again.')}
function images(){document.querySelectorAll('.avatar img').forEach(i=>i.onerror=()=>{i.hidden=true;i.nextElementSibling.hidden=false})}
function footer(){return '<footer><a href="/about">How it works</a><a href="/support">Help & support</a><a href="/billing">Buy gas</a><span>Independent. Not affiliated with LinkedIn.</span></footer>'}
function shell(content){$('#app').innerHTML=content+footer();images();document.querySelectorAll('[data-fill]').forEach(b=>b.onclick=fill);tick()}
function login(){if(window.linkdidLogin)return window.linkdidLogin();return '<section class="page-state"><h1>Your spotlight starts here.</h1><p>Sign in, create your profile, then tap the pump to earn gas.</p><a class="button dark" href="/signin-with-chatgpt?return_to='+encodeURIComponent('/account'+location.search)+'" target="_top">Sign in with ChatGPT →</a></section>'}
function active(){return !!account?.claim&&account.claim.expires>now()}
function claimCard(){const c=account?.claim,on=active();return '<section class="fuel-card '+(on?'is-active':'is-ready')+'" id="fuel-card" data-active="'+on+'"><div class="fuel-heading"><span class="fuel-icon" aria-hidden="true">⛽</span><span class="free-badge">FREE. EVERY DAY.</span></div><span class="eyebrow">'+(on?'YOUR SPOTLIGHT IS LIVE':'YOUR NEXT SPOT STARTS HERE')+'</span><h2>'+(on?'You’re on the board.':'Fill Gas.<br>Take your spot.')+'</h2><p>'+(on?'Your profile is visible. Come back when your gas runs out.':account?.profile?'Your profile is ready. One click starts your free 24-hour claim.':'Create your profile, then claim 24 hours of visibility for free.')+'</p><div class="fuel-time"><strong '+(on?'data-time="'+c.expires+'"':'')+'>'+(on?remaining(c.expires):'24<span>hours</span>')+'</strong><span>'+(on?'remaining in your spotlight':'of free profile visibility')+'</span></div><div class="gas-track" role="img" aria-label="'+(on?'Remaining gas':'Ready to fill')+'"><div '+(on?'data-fuel="'+c.expires+'"':'class="ready-fuel"')+'></div></div><div class="fuel-numbers"><div><strong data-own-rank>'+(on&&account.rank?'#'+account.rank:'—')+'</strong><span>Your rank</span></div><div><strong>'+(on?c.streak:(account?.history?.[0]?.expires>=now()-86400000?account.history[0].streak:0)||0)+'</strong><span>Claim streak</span></div><div><strong>$0</strong><span>Always free</span></div></div><p id="claim-error" class="claim-error" role="alert">'+esc(claimError)+'</p><button class="button dark full fuel-cta" data-fill '+(on||claimBusy?'disabled':'')+'>'+(on?'✓ Claim active':claimBusy?'Filling your gas…':'⛽ Fill Gas — Free →')+'</button>'+(on?'<a class="fuel-view" href="/profile/'+account.profile.id+'">View your live profile ↗</a>':'<p class="fuel-footnote">No payment · No paid boosts · First come, first served</p>')+'</section>'}
function livePeople(){return people.filter(p=>p.expires>now()).sort((a,b)=>a.sequence-b.sequence).map((p,i)=>({...p,rank:i+1}))}
function rows(){const all=livePeople(),list=all.filter(p=>(filter==='All people'||p.category===filter)&&(!search||(p.name+' '+p.headline+' '+p.location).toLowerCase().includes(search)));if(!$('#profiles'))return;$('#count').textContent=all.length+' active';$('#profiles').innerHTML=list.length?list.map(p=>'<article class="profile '+(p.rank===1?'first':'')+'"><span class="rank">#'+p.rank+'</span>'+avatar(p)+'<div><div class="person-name"><a href="/profile/'+p.id+'">'+esc(p.name)+'</a>'+(p.id===account?.profile?.id?'<span class="tag">You</span>':'')+'</div><p class="headline">'+esc(p.headline)+'</p><div class="meta"><span class="tag">'+esc(p.category)+'</span><span>'+esc(p.location)+'</span>'+(p.streak>1?'<span>🔥 '+p.streak+' claims</span>':'')+'</div></div><div class="gas-cell"><strong data-time="'+p.expires+'">'+remaining(p.expires)+'</strong><span>gas remaining</span><a href="/profile/'+p.id+'">View profile ↗</a></div></article>').join(''):'<div class="page-state"><h2>'+(all.length?'No matching professionals.':'The first spot is yours to claim.')+'</h2><p>'+(all.length?'Try another specialty or search.':'Create your profile and fill your gas to start the leaderboard.')+'</p><button class="button dark" data-fill>⛽ Fill Gas — Free</button></div>';images();document.querySelectorAll('#profiles [data-fill]').forEach(b=>b.onclick=fill)}
function home(){document.title='Linkdid — Fill Gas. Get discovered.';shell('<section class="free-hero"><div><span class="eyebrow">THE FREE PROFESSIONAL LEADERBOARD</span><h1>Fill your gas.<br><span>Get discovered.</span></h1><p>One free claim. 24 hours in the spotlight.<br>First to claim, first in line.</p><div class="hero-pills"><span>⛽ Free daily claims</span><span>◷ 24-hour visibility</span><span>↗ Meet professionals</span></div></div>'+claimCard()+'</section><div class="how-strip"><span><b>01</b> Create your profile</span><span><b>02</b> Fill Gas for free</span><span><b>03</b> Come back after 24 hours</span></div><section class="leaderboard"><div class="board-heading"><h2>In the spotlight <span id="count"></span></h2><button class="text-btn" id="refresh">Refresh ↻</button></div><div class="filters">'+['All people',...cats].map(c=>'<button class="filter '+(filter===c?'active':'')+'" data-filter="'+c+'" aria-pressed="'+(filter===c)+'">'+c+'</button>').join('')+'</div><div class="search-row"><label class="search"><span>⌕</span><input id="search" type="search" placeholder="Search people, skills or location" aria-label="Search professionals" value="'+esc(search)+'"></label><span>Earliest active claim first</span></div><div id="profiles"></div><div class="board-footer"><span>Free placement · no paid boosts</span><span id="refresh-note">Updates every 30 seconds</span></div></section>');rows();$('#search').oninput=e=>{search=e.target.value.toLowerCase();rows()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});rows()});$('#refresh').onclick=()=>refresh(true)}
async function fill(){if(claimBusy)return;claimError='';if(!session?.user){location.href='/account?claim=1';return}if(!account?.profile){if($('#profile-form')){$('#profile-form').scrollIntoView({behavior:'smooth',block:'center'});$('#profile-form').elements.name.focus();toast('Add your profile, then select Save profile & Fill Gas.')}else location.href='/account?claim=1';return}if(active())return;claimBusy=true;updateFuel();claimID=claimID||crypto.randomUUID();try{const result=await api('/api/claim',{id:claimID});if(!result.active){claimID=null;throw Error('This old claim has expired. Click Fill Gas again to create a new claim.')}claimID=null;account.claim=result.claim;await loadState();updateFuel();if($('#profiles'))rows();if(['/categories','/rules','/faq','/stats'].includes(location.pathname))directoryPage();else if(location.pathname==='/claim')await claimPage();else if(location.pathname==='/account')dashboard();toast('You’re live! Your gas lasts for 24 hours.')}catch(e){claimError=e.message;toast(e.message)}finally{claimBusy=false;updateFuel()}}
function updateFuel(){if($('#fuel-card')){$('#fuel-card').outerHTML=claimCard();$('#fuel-card [data-fill]').onclick=fill}tick()}
function tick(){const card=$('#fuel-card');if(card&&card.dataset.active!==String(active())){updateFuel();return}const own=livePeople().find(p=>p.id===account?.profile?.id);if(own&&$('[data-own-rank]'))$('[data-own-rank]').textContent='#'+own.rank;document.querySelectorAll('[data-time]').forEach(x=>x.textContent=remaining(Number(x.dataset.time)));document.querySelectorAll('[data-fuel]').forEach(x=>x.style.width=Math.max(0,Math.min(100,(Number(x.dataset.fuel)-now())/864000))+'%');const b=$('#fuel-card [data-fill]');if(b){b.disabled=active()||claimBusy;b.textContent=active()?'✓ Claim active':claimBusy?'Filling your gas…':'⛽ Fill Gas — Free →';if(!active()&&$('[data-own-rank]'))$('[data-own-rank]').textContent='—'}}
async function loadState(){const generation=++stateLoad;const [d,a]=await Promise.all([api('/api/profiles'),session?.user?api('/api/account'):null]);if(generation!==stateLoad)return;people=d.profiles;if(a)account=a}
async function refresh(manual=false){if(refreshBusy)return;refreshBusy=true;try{await loadState();if($('#profiles'))rows();updateFuel();if($('#refresh-note'))$('#refresh-note').textContent='Updated '+new Date().toLocaleTimeString();if(manual)toast('Leaderboard refreshed.')}catch(e){if(manual)toast(e.message);if($('#refresh-note'))$('#refresh-note').textContent='Could not refresh. Try again.'}finally{refreshBusy=false}}
function dashboard(){document.title='Your dashboard — Linkdid';if(!session.user){shell(login());return}const p=account?.profile,n=account.notifications||[],h=account.history||[];shell('<section class="account-wrap"><div class="account-subnav"><a href="/">← Leaderboard</a><a href="/support">Support</a>'+(session.admin?'<a href="/admin">Support inbox</a>':'')+'<a href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a></div><h1>Your daily spotlight.</h1><p>'+esc(session.user.email)+'</p><div class="account-grid"><div>'+claimCard()+'<section class="panel"><h2>'+(p?'Your profile':'First, create your profile')+'</h2><form id="profile-form">'+profilePhotoField(p)+'<label>Name<input name="name" required maxlength="60" value="'+esc(p?.name)+'"></label><label>What do you do?<input name="headline" required maxlength="160" value="'+esc(p?.headline)+'" placeholder="Helping founders build better products"></label><label>LinkedIn profile link<input name="url" type="url" required value="'+esc(p?.url)+'" placeholder="https://www.linkedin.com/in/your-name"></label><label>Specialty<select name="category">'+cats.map(c=>'<option '+(c===p?.category?'selected':'')+'>'+c+'</option>').join('')+'</select></label><label>Location<input name="location" maxlength="80" value="'+esc(p?.location)+'"></label><p class="error-message" id="profile-error" role="alert"></p><button class="button dark">'+(p?'Save profile':'Save profile & start pumping →')+'</button></form></section></div><div><section class="panel"><h2>Your profile at a glance</h2><div class="stats-grid"><div class="stat"><strong>'+account.stats.views+'</strong><span>Profile views</span></div><div class="stat"><strong>'+account.stats.clicks+'</strong><span>LinkedIn clicks</span></div></div><p>Unique signed-in visitors per day, excluding you. These are Linkdid metrics.</p>'+(p?'<a class="secondary-btn" href="/profile/'+p.id+'">View your profile ↗</a>':'')+'</section><section class="panel"><h2>Claim history</h2><p>Refill within 24 hours after expiry to continue your streak. Streaks are badges only.</p>'+(h.length?'<div class="scroll-table"><table class="history"><thead><tr><th>Claimed</th><th>Status</th><th>Streak</th></tr></thead><tbody>'+h.map(c=>'<tr><td>'+esc(date(c.started))+'</td><td data-claim-status="'+c.expires+'">'+(c.expires>now()?'Active':'Expired')+'</td><td>'+c.streak+'</td></tr>').join('')+'</tbody></table></div>':'<p>No claims yet. Fill your gas to join the leaderboard.</p>')+'</section><section class="panel"><div class="panel-header"><h2>Notifications</h2><button class="text-btn" id="mark-read">Mark read</button></div>'+(n.length?n.map(x=>'<div class="notification '+(!x.read?'unread':'')+'">'+esc(x.message)+'<time>'+esc(date(x.created))+'</time></div>').join(''):'<p>No notifications yet. Your gas balances appear above. Email alerts are not enabled.</p>')+'</section></div></div></section>');
 const releasePhotoPreview=bindProfilePhoto($('#profile-form'));
 $('#profile-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#profile-error').textContent='';b.textContent=p?'Saving…':'Saving your profile…';try{const fields=new FormData(e.target),photo=e.target.elements.photo.files[0];fields.delete('photo');await api('/api/profile',Object.fromEntries(fields));if(photo){b.textContent='Uploading photo…';try{await uploadProfilePhoto(photo)}catch(error){throw Error('Profile saved, but photo could not upload: '+error.message)}}releasePhotoPreview();await loadState();if(!p||new URLSearchParams(location.search).get('next')==='/claim'){const q=new URLSearchParams(location.search);q.delete('next');q.delete('profileLink');q.delete('specialty');location.href='/claim'+(q.size?'?'+q.toString():'');return}dashboard();toast('Profile saved.');$('#fuel-card').scrollIntoView({behavior:'smooth',block:'center'})}catch(e){$('#profile-error').textContent=e.message}finally{b.disabled=false;b.textContent=p?'Save profile':'Save profile & start pumping →'}};

 $('#mark-read').onclick=async()=>{try{await api('/api/notifications/read',{});await loadState();dashboard()}catch(e){toast(e.message)}};
}
async function profilePage(){const id=location.pathname.split('/')[2],d=await api('/api/profile/'+id),p=d.profile;document.title=p.name+' — Linkdid';shell('<section class="profile-detail"><a href="/">← Leaderboard</a><div class="panel">'+avatar(p)+'<h1>'+esc(p.name)+'</h1><p>'+esc(p.headline)+'</p><div class="meta"><span class="tag">'+esc(p.category)+'</span><span>'+esc(p.location)+'</span></div><div class="profile-claim-status" data-detail-expires="'+(d.claim?.expires||0)+'">'+(d.claim?'<h2>#'+d.rank+' in the spotlight</h2><strong data-time="'+d.claim.expires+'">'+remaining(d.claim.expires)+'</strong><p>Gas remaining · active profile</p>':'<h2>Currently off the leaderboard</h2><p>This profile has no active claim.</p>')+'</div><div class="profile-actions"><a class="button dark" href="/go/'+p.id+'" target="_blank" rel="noopener">View on LinkedIn ↗</a><button class="secondary-btn" id="share">Copy profile link</button>'+(account?.profile?.id===p.id?'<a class="secondary-btn" href="/account">Manage your gas</a>':'')+'</div><p>Self-submitted profile. LinkedIn ownership has not been verified.</p></div></section>');$('#share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Profile link copied.')}catch{toast('Copy this page’s address to share.')}};if(session.user)api('/api/view/'+id,{}).catch(()=>{})}
function about(){shell('<section class="account-wrap"><span class="eyebrow">HOW LINKDID WORKS</span><h1>A little gas. A daily spotlight.</h1><section class="panel"><h2>Free, first come, first served.</h2><ol><li>Create your professional profile.</li><li>Click <b>Fill Gas — Free</b>. Your 24-hour timer starts immediately.</li><li>Earlier active claims appear above later claims.</li><li>When your gas expires, your profile leaves the leaderboard. Your account and profile stay saved.</li><li>Fill again to rejoin at the end of the active line.</li></ol><p>Your profile is active for 24 hours, but a #1 position is not guaranteed for 24 hours. Your timer keeps running while you wait in line.</p><p>You cannot refill an active claim. Simultaneous claims follow the server’s recorded order. Streaks continue when you return within 24 hours of expiry; they never change rank.</p><p>No payment, paid boosts, or bids affect this leaderboard. Placement applies to Linkdid only and does not guarantee clients or LinkedIn reach.</p><button class="button dark" data-fill>⛽ Fill Gas — Free</button></section></section>')}
async function support(){if(!session.user){shell(login());return}const d=await api('/api/support');shell('<section class="account-wrap"><h1>Help & support</h1><div class="account-grid"><section class="panel"><h2>Send a request</h2><p>Describe your issue. Never include passwords or wallet secrets. Requests are saved for the operator; email delivery is not enabled.</p><form id="support-form"><label>Subject<input name="subject" required maxlength="100"></label><label>Details<textarea name="message" rows="6" required maxlength="2000"></textarea></label><p class="error-message" id="support-error" role="alert"></p><button class="button dark">Submit request</button></form></section><section class="panel"><h2>Your requests</h2>'+ (d.tickets.map(t=>'<article class="support-item"><h3>'+esc(t.subject)+'</h3><span class="tag">'+esc(t.status.replace('_',' '))+'</span><p>'+esc(t.message)+'</p><small>'+esc(date(t.created))+'</small></article>').join('')||'<p>No requests yet.</p>')+'</section></div></section>');$('#support-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/support',Object.fromEntries(new FormData(e.target)));await support();toast('Request saved.')}catch(e){$('#support-error').textContent=e.message}finally{b.disabled=false}}}
async function pastPayments(){if(!session.user){shell(login());return}const d=await api('/api/crypto/orders');shell('<section class="account-wrap"><h1>Past payments</h1><p>Linkdid now uses free claims. New payments are disabled; previous records are retained.</p><section class="panel">'+(d.orders.map(o=>'<article class="support-item"><h2>$'+Number(o.amount)+' · '+esc(o.status)+'</h2><p>'+esc(o.id)+'</p>'+(o.status==='credited'?'<a href="/api/crypto/orders/'+o.id+'/receipt">Download receipt</a>':o.paymentId?'<button class="secondary-btn" data-check="'+o.id+'">Check past payment</button>':'')+'</article>').join('')||'<p>No past payments.</p>')+'</section></section>');document.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/crypto/orders/'+b.dataset.check+'/check',{});await pastPayments()}catch(e){toast(e.message)}finally{b.disabled=false}})}
async function admin(){if(!session.admin){shell('<section class="page-state"><h1>Operator access required</h1><a href="/account">My dashboard</a></section>');return}const d=await api('/api/admin/support');shell('<section class="account-wrap"><h1>Support inbox</h1><section class="panel">'+(d.tickets.map(t=>'<article class="support-item"><h2>'+esc(t.subject)+'</h2><p>'+esc(t.message)+'</p><label>Status<select data-ticket="'+t.id+'">'+['open','in_review','resolved'].map(s=>'<option '+(s===t.status?'selected':'')+' value="'+s+'">'+s.replace('_',' ')+'</option>').join('')+'</select></label></article>').join('')||'<p>No requests.</p>')+'</section></section>');document.querySelectorAll('[data-ticket]').forEach(s=>s.onchange=async()=>{s.disabled=true;try{await api('/api/admin/support',{id:s.dataset.ticket,status:s.value});toast('Status saved.')}catch(e){toast(e.message)}finally{s.disabled=false}})}
async function boot(){try{if(location.pathname==='/signin'&&window.linkdidSignIn){await window.linkdidSignIn();return}if(['/account','/claim','/billing','/support','/admin'].includes(location.pathname)&&window.linkdidRequireSignIn&&!await window.linkdidRequireSignIn())return;const state=await api('/api/bootstrap');session=state.session;people=state.profiles;account=state.account;peopleAt=state.serverNow;accountAt=state.serverNow;directoryStats=state.stats||{};if(account?.gas)pumpProgress=account.gas.progress;if(location.pathname==='/claim'&&new URLSearchParams(location.search).get('mode')==='free')await window.ensurePump?.();if(['/categories','/rules','/faq','/stats'].includes(location.pathname))directoryPage();else if(location.pathname==='/claim')await claimPage();else if(location.pathname==='/account')dashboard();else if(location.pathname.startsWith('/profile/'))await profilePage();else if(location.pathname==='/support')await support();else if(location.pathname==='/admin')await admin();else if(location.pathname==='/billing')await pastPayments();else if(location.pathname==='/about')about();else home()}catch(e){shell('<section class="page-state"><h1>Could not load this page.</h1><p>'+esc(e.message)+'</p><button class="button dark" id="retry">Try again</button><a href="/">Back to leaderboard</a></section>');$('#retry').onclick=boot}}
setInterval(()=>{tick();document.querySelectorAll('[data-claim-status]').forEach(x=>x.textContent=Number(x.dataset.claimStatus)>now()?'Active':'Expired');if($('#profiles')&&people.some(p=>p.expires<=now())){people=people.filter(p=>p.expires>now());rows()}const detail=$('[data-detail-expires]');if(detail&&Number(detail.dataset.detailExpires)>0&&Number(detail.dataset.detailExpires)<=now()){detail.dataset.detailExpires='0';detail.innerHTML='<h2>Currently off the leaderboard</h2><p>This claim has expired.</p>'}},1000);
setInterval(()=>{if(document.visibilityState==='visible'&&['/','/daily','/account','/claim','/paid'].includes(location.pathname))refresh()},30000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh()});
